        "statement": "Dans le sang (pH initial 7.4, Ka = 4.3x10^-7, Ctotale = 0.5x10^-2 mol/L), on injecte un acide fort Actif-H2 (4.0x10^-3 mol/L). Quelles sont les affirmations vraies ?",
