        "explanation": "Propositions exactes : B, D, E\nA. Faux : C'est l'eau pure qui sert de valeur de référence zéro (0 UH). L'air est à -1000 UH.\nB. Vrai : Formule officielle de la densité Hounsfield.\nC. Faux : La graisse a une densité UH négative (environ -100 UH à -50 UH).\nD. Vrai : Les os très denses ont des valeurs élevées de +300 UH à +1000+ UH.\nE. Vrai : Les tissus mous (foie, reins, muscles) sont compris entre +20 et +50 UH."
