        "explanation": "Propositions exactes : A, B, C, D\nA. Vrai : Le contraste naturel dépend de l'atténuation propre des tissus, le contraste radiologique inclut les paramètres d'acquisition et PDC.\nB. Vrai : Les 4 densités fondamentales sont l'Air (-1000), la Graisse (-100), l'Eau (0) et l'Os (+1000).\nC. Vrai : Le muscle est un tissu mou (~40 UH) de densité intermédiaire (gris moyen).\nD. Vrai : L'os est fortement atténuant et apparaît très radio-opaque (blanc brillant).\nE. Faux : La graisse a une densité négative (~-100 UH) et apparaît en gris sombre/noir."
